// Load candidate profile and jobs array
const input = $input.first().json;
const candidate = input.candidate_profile;
const jobs = input.jobs;

if (!candidate || !jobs || !Array.isArray(jobs)) {
  throw new Error('CONTRACT ERROR: Module 3 requires candidate_profile and jobs array');
}

return [{ json: { candidate, jobs } }];

// Hybrid Matcher with Keyword Overlap, Semantic Score, Experience Check & Explainability
const data = $input.first().json;
const cand = data.candidate;
const jobs = data.jobs;

// Synonym normalization map
const synonyms = {
  'js': 'javascript',
  'ts': 'typescript',
  'py': 'python',
  'postgres': 'postgresql',
  'k8s': 'kubernetes'
};

function normalizeSkill(s) {
  const lower = (s || '').toLowerCase().trim();
  return synonyms[lower] || lower;
}

const candSkills = new Set([
  ...(cand.technical_skills || []),
  ...(cand.programming_languages || []),
  ...(cand.frameworks || []),
  ...(cand.tools || [])
].map(normalizeSkill));

const ranked = jobs.map(job => {
  const reqSkills = (job.required_skills || []).map(normalizeSkill);
  const prefSkills = (job.preferred_skills || []).map(normalizeSkill);

  const matched = reqSkills.filter(s => candSkills.has(s));
  const missing = reqSkills.filter(s => !candSkills.has(s));

  const skillScore = reqSkills.length > 0 ? (matched.length / reqSkills.length) * 100 : 70.0;
  const prefMatched = prefSkills.filter(s => candSkills.has(s));
  const prefScore = prefSkills.length > 0 ? (prefMatched.length / prefSkills.length) * 100 : 50.0;

  const reqYears = job.required_experience_years || 0;
  const candYears = cand.experience_years || 0;
  const expSatisfied = candYears >= reqYears;
  const expScore = expSatisfied ? 100.0 : Math.max(0, (candYears / reqYears) * 100);

  // Simulated semantic similarity (0.0 to 1.0)
  const semanticSim = Math.min(1.0, (skillScore / 100) * 0.7 + (expSatisfied ? 0.3 : 0.1));
  const semanticScore = semanticSim * 100;

  // Weighted Hybrid Formula: 40% Skills, 30% Semantic, 20% Exp, 10% Preferred
  const finalScore = Math.round(
    (skillScore * 0.40 + semanticScore * 0.30 + expScore * 0.20 + prefScore * 0.10) * 10
  ) / 10;

  let decision = 'REJECT';
  if (finalScore >= 75.0) decision = 'APPLY';
  else if (finalScore >= 50.0) decision = 'REVIEW';

  const explanation = `${matched.length}/${reqSkills.length} required skills matched (${matched.join(', ') || 'none'}). Experience check: ${candYears}y vs ${reqYears}y required (${expSatisfied ? 'Satisfied' : 'Deficit'}). Final score: ${finalScore}.`;

  return {
    schema_version: '1.0',
    job_id: job.job_id,
    job_title: job.job_title,
    company: job.company,
    application_url: job.application_url,
    match_score: finalScore,
    score_breakdown: {
      skill_score: skillScore,
      skill_weight: 0.40,
      semantic_score: semanticScore,
      semantic_weight: 0.30,
      experience_score: expScore,
      experience_weight: 0.20,
      preferred_skill_score: prefScore,
      preferred_skill_weight: 0.10
    },
    matched_skills: matched,
    missing_skills: missing,
    experience_match: {
      candidate_years: candYears,
      required_years: reqYears,
      satisfied: expSatisfied
    },
    semantic_similarity: Math.round(semanticSim * 100) / 100,
    decision: decision,
    explanation: explanation,
    method: 'hybrid_v1',
    ranked_at: new Date().toISOString()
  };
});

// Sort descending with tie-breakers
ranked.sort((a, b) => {
  if (b.match_score !== a.match_score) return b.match_score - a.match_score;
  return b.semantic_similarity - a.semantic_similarity;
});

return [{ json: ranked }];
